import sys

MOD = 998244353

def mod(num):
    return num % MOD

def mul(*args):
    if not args:
        raise ValueError('参数不能为空')
    if len(args) == 1:
        return args[0]
    result = 1
    for a in args:
        result = (result * a) % MOD
    return result

def get_primes(n):
    nums = [1] * (n + 1)
    nums[0] = nums[1] = 0
    primes = []
    for i in range(2, n + 1):
        if nums[i]:
            primes.append(i)
        for p in primes:
            if p * i > n:
                break
            nums[p * i] = 0
            if i % p == 0:
                break
    return nums

def solve(read):
    rns = lambda: list(map(int, read().split()))
    n, m = rns()
    pre = 1
    M = mod(m)
    res = 0
    ans = M
    ans1 = M
    p = get_primes(n + 10)
    for i in range(2, n + 1):
        if pre <= m and p[i]:
            pre = pre * i
        if pre > m:
            ans = 0
        else:
            ans = mul(ans, m // pre)
        ans1 = mul(ans1, M)
        res = mod(res + ans1 - ans)
    return res

def main():
    data = sys.stdin.read().split('\n')
    it = iter(data)
    def read():
        return next(it, '')
    t = 1
    res = []
    for _ in range(t):
        s = solve(read)
        res.append(str(s))
    sys.stdout.write('\n'.join(res))

if __name__ == '__main__':
    main()

